"""Tests for reservation validation and capacity limits."""

import unittest

from reservations import release, reserve


class ReserveTests(unittest.TestCase):
    def test_success(self):
        for args, expected in (
            ((10, 3, 2), 5),
            ((10, 0, 4), 4),
            ((10, 3, 0), 3),
        ):
            with self.subTest(args=args):
                self.assertEqual(reserve(*args), expected)

    def test_full_capacity(self):
        for args in ((10, 3, 7), (10, 10, 0), (0, 0, 0)):
            with self.subTest(args=args):
                self.assertEqual(reserve(*args), args[0])

    def test_invalid_input(self):
        invalid_values = (-1, True, False, 1.0, "1", None, 1j, [], {})
        for position in range(3):
            for value in invalid_values:
                args = [10, 2, 3]
                args[position] = value
                with self.subTest(position=position, value=value):
                    with self.assertRaises(ValueError):
                        reserve(*args)

    def test_over_capacity(self):
        for args in ((10, 8, 3), (10, 10, 1), (10, 11, 0), (0, 0, 1)):
            with self.subTest(args=args):
                with self.assertRaises(ValueError):
                    reserve(*args)


class ReleaseTests(unittest.TestCase):
    def test_success(self):
        for args, expected in (((10, 3), 7), ((10, 0), 10)):
            with self.subTest(args=args):
                self.assertEqual(release(*args), expected)

    def test_release_all(self):
        for args in ((10, 10), (0, 0)):
            with self.subTest(args=args):
                self.assertEqual(release(*args), 0)

    def test_invalid_input(self):
        invalid_values = (-1, True, False, 1.0, "1", None, 1j, [], {})
        for position in range(2):
            for value in invalid_values:
                args = [10, 3]
                args[position] = value
                with self.subTest(position=position, value=value):
                    with self.assertRaises(ValueError):
                        release(*args)

    def test_count_exceeds_booked(self):
        for args in ((10, 11), (0, 1)):
            with self.subTest(args=args):
                with self.assertRaises(ValueError):
                    release(*args)


if __name__ == "__main__":
    unittest.main()

