"""Validate and apply reservations."""


def reserve(capacity, booked, requested):
    """Return the new booking total, raising ValueError for invalid reservations."""
    for value in (capacity, booked, requested):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError("Arguments must be nonnegative integers, excluding booleans")

    total = booked + requested
    if total > capacity:
        raise ValueError("Reservation exceeds capacity")
    return total


def release(booked, count):
    """Return the remaining bookings, raising ValueError for invalid releases."""
    for value in (booked, count):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError("Arguments must be nonnegative integers, excluding booleans")

    if count > booked:
        raise ValueError("Release exceeds booked reservations")
    return booked - count
